-- MariaDB business schema converted to PostgreSQL. No user data.

begin;

create table public.admins (
  "admin_id" bigint generated by default as identity primary key,
  "user_id" bigint default NULL,
  "first_name" varchar(100) not null,
  "last_name" varchar(100) not null,
  "ic_number" varchar(20) not null,
  "phone" varchar(20) not null,
  "department" varchar(100) default NULL,
  "created_at" timestamptz not null default now(),
  "profile_picture" varchar(255) default NULL
);

alter table public.admins enable row level security;
revoke all on public.admins from anon, authenticated;

create table public.appointments (
  "appointment_id" bigint generated by default as identity primary key,
  "patient_id" bigint not null,
  "doctor_id" bigint not null,
  "appointment_date" date not null,
  "appointment_time" time not null,
  "status" text default 'pending' check ("status" in ('pending','confirmed','completed','cancelled')),
  "payment_status" text default 'unpaid' check ("payment_status" in ('unpaid','pending','paid')),
  "reason" text default NULL,
  "symptoms" text default NULL,
  "qr_code" varchar(255) default NULL,
  "confirmation_deadline" timestamptz default NULL,
  "confirmed_at" timestamptz default NULL,
  "confirmation_reminder_sent" bigint default 0,
  "checked_in_at" timestamptz default NULL,
  "checked_in_by" bigint default NULL,
  "created_at" timestamptz not null default now(),
  "updated_at" timestamptz not null default now()
);

alter table public.appointments enable row level security;
revoke all on public.appointments from anon, authenticated;

create table public.chatbot_knowledge (
  "knowledge_id" bigint generated by default as identity primary key,
  "rule_type" text not null check ("rule_type" in ('allowed','restricted')),
  "category" varchar(100) default NULL,
  "topic" varchar(255) not null,
  "keywords" text not null,
  "response_text" text not null,
  "severity" text default 'low' check ("severity" in ('low','medium','high')),
  "requires_login" bigint default 0,
  "is_active" bigint default 1,
  "created_at" timestamptz not null default now(),
  "updated_at" timestamptz not null default now()
);

alter table public.chatbot_knowledge enable row level security;
revoke all on public.chatbot_knowledge from anon, authenticated;

create table public.chatbot_logs (
  "chatbot_id" bigint generated by default as identity primary key,
  "patient_id" bigint default NULL,
  "session_id" varchar(255) not null,
  "user_message" text not null,
  "bot_response" text not null,
  "knowledge_id" bigint default NULL,
  "is_restricted" bigint default 0,
  "created_at" timestamptz not null default now()
);

alter table public.chatbot_logs enable row level security;
revoke all on public.chatbot_logs from anon, authenticated;

create table public.clinic_catalog (
  "catalog_id" bigint generated by default as identity primary key,
  "item_type" text not null check ("item_type" in ('medicine','lab_test','procedure')),
  "name" varchar(255) not null,
  "category" varchar(100) default NULL,
  "price" decimal(10,2) not null,
  "description" text default NULL,
  "is_active" bigint default 1,
  "metadata" jsonb default NULL,
  "created_at" timestamptz not null default now(),
  "updated_at" timestamptz not null default now()
);

alter table public.clinic_catalog enable row level security;
revoke all on public.clinic_catalog from anon, authenticated;

create table public.contact_submissions (
  "contact_id" bigint generated by default as identity primary key,
  "name" varchar(255) not null,
  "email" varchar(255) not null,
  "phone" varchar(20) default NULL,
  "subject" varchar(100) not null,
  "message" text not null,
  "ip_address" varchar(45) default NULL,
  "status" text default 'new' check ("status" in ('new','read','closed')),
  "created_at" timestamptz not null default now()
);

alter table public.contact_submissions enable row level security;
revoke all on public.contact_submissions from anon, authenticated;

create table public.doctors (
  "doctor_id" bigint generated by default as identity primary key,
  "user_id" bigint default NULL,
  "ic_number" varchar(20) default NULL,
  "date_of_birth" date default NULL,
  "gender" text default NULL check ("gender" in ('male','female')),
  "first_name" varchar(100) not null,
  "last_name" varchar(100) not null,
  "specialization" varchar(100) default NULL,
  "license_number" varchar(50) not null,
  "qualifications" text default NULL,
  "bio" text default NULL,
  "experience_years" bigint default 0,
  "profile_picture" varchar(255) default NULL,
  "status" text default 'active' check ("status" in ('active','inactive','on_leave')),
  "phone" varchar(20) not null,
  "consultation_fee" decimal(10,2) default 0.00,
  "available_days" jsonb default NULL,
  "available_hours" varchar(50) default NULL,
  "created_at" timestamptz not null default now()
);

alter table public.doctors enable row level security;
revoke all on public.doctors from anon, authenticated;

create table public.medical_records (
  "record_id" bigint generated by default as identity primary key,
  "patient_id" bigint not null,
  "doctor_id" bigint not null,
  "appointment_id" bigint default NULL,
  "visit_date" date not null,
  "diagnosis" text default NULL,
  "prescription" text default NULL,
  "symptoms" text default NULL,
  "lab_results" text default NULL,
  "notes" text default NULL,
  "created_at" timestamptz not null default now(),
  "updated_at" timestamptz not null default now()
);

alter table public.medical_records enable row level security;
revoke all on public.medical_records from anon, authenticated;

create table public.notifications (
  "notification_id" bigint generated by default as identity primary key,
  "user_id" bigint not null,
  "notification_type" text not null default 'general' check ("notification_type" in ('appointment','payment','reminder','general','system','cancellation','reschedule')),
  "title" varchar(255) not null,
  "message" text not null,
  "is_read" bigint default 0,
  "created_at" timestamptz not null default now()
);

alter table public.notifications enable row level security;
revoke all on public.notifications from anon, authenticated;

create table public.patients (
  "patient_id" bigint generated by default as identity primary key,
  "user_id" bigint default NULL,
  "first_name" varchar(100) not null,
  "last_name" varchar(100) not null,
  "ic_number" varchar(20) not null,
  "date_of_birth" date not null,
  "gender" text not null check ("gender" in ('male','female')),
  "phone" varchar(20) not null,
  "address" text default NULL,
  "emergency_contact" varchar(50) default NULL,
  "profile_picture" varchar(255) default NULL,
  "blood_type" varchar(5) default NULL,
  "allergies" text default NULL,
  "created_at" timestamptz not null default now()
);

alter table public.patients enable row level security;
revoke all on public.patients from anon, authenticated;

create table public.payments (
  "payment_id" bigint generated by default as identity primary key,
  "patient_id" bigint not null,
  "appointment_id" bigint default NULL,
  "amount" decimal(10,2) not null,
  "payment_method" text not null check ("payment_method" in ('cash','card','online')),
  "payment_status" text default 'pending' check ("payment_status" in ('pending','completed','failed','refunded')),
  "receipt_number" varchar(50) default NULL,
  "transaction_id" varchar(100) default NULL,
  "payment_date" timestamptz not null default now(),
  "payment_details" jsonb default NULL
);

alter table public.payments enable row level security;
revoke all on public.payments from anon, authenticated;

create table public.prescriptions (
  "prescription_id" bigint generated by default as identity primary key,
  "patient_id" bigint not null,
  "doctor_id" bigint not null,
  "diagnosis" varchar(500) not null,
  "notes" text default NULL,
  "verification_code" varchar(20) default NULL,
  "valid_until" date default NULL,
  "status" text default 'active' check ("status" in ('active','fulfilled','expired','cancelled')),
  "prescription_date" timestamptz not null default now(),
  "created_at" timestamptz not null default now(),
  "updated_at" timestamptz not null default now(),
  "medications_json" jsonb default NULL,
  "appointment_id" bigint default NULL
);

alter table public.prescriptions enable row level security;
revoke all on public.prescriptions from anon, authenticated;

create table public.qr_event_logs (
  "qr_id" bigint generated by default as identity primary key,
  "appointment_id" bigint not null,
  "qr_code" varchar(255) not null,
  "event_type" text not null check ("event_type" in ('generated','regenerated','revoked','scanned')),
  "doctor_id" bigint not null,
  "event_time" timestamptz default now(),
  "status" varchar(50) default NULL,
  "details" jsonb default NULL,
  "ip_address" varchar(45) default NULL
);

alter table public.qr_event_logs enable row level security;
revoke all on public.qr_event_logs from anon, authenticated;

create table public.reviews (
  "review_id" bigint generated by default as identity primary key,
  "doctor_id" bigint not null,
  "patient_id" bigint not null,
  "appointment_id" bigint not null,
  "rating" bigint not null,
  "review_text" text default NULL,
  "created_at" timestamptz not null default now(),
  "updated_at" timestamptz not null default now()
);

alter table public.reviews enable row level security;
revoke all on public.reviews from anon, authenticated;

create table public.symptom_checks (
  "symptom_check_id" bigint generated by default as identity primary key,
  "user_id" bigint not null,
  "patient_id" bigint not null,
  "status" text default 'completed' check ("status" in ('visited','completed')),
  "symptoms" text not null,
  "analysis_details" jsonb default NULL,
  "duration" varchar(100) default NULL,
  "age" bigint default NULL,
  "additional_info" text default NULL,
  "response" text default NULL,
  "ip_address" varchar(45) default NULL,
  "urgency_level" varchar(20) default 'routine',
  "created_at" timestamptz not null default now()
);

alter table public.symptom_checks enable row level security;
revoke all on public.symptom_checks from anon, authenticated;

create table public.symptom_scope (
  "scope_id" bigint generated by default as identity primary key,
  "symptom_name" varchar(255) not null,
  "category" varchar(100) not null,
  "possible_conditions" text default NULL,
  "urgency_level" text default 'routine' check ("urgency_level" in ('routine','urgent','emergency')),
  "warning_keywords" text default NULL,
  "guidance" text default NULL,
  "recommended_specialization" varchar(100) default NULL,
  "is_active" bigint default 1,
  "created_at" timestamptz not null default now(),
  "updated_at" timestamptz not null default now()
);

alter table public.symptom_scope enable row level security;
revoke all on public.symptom_scope from anon, authenticated;

create table public.users (
  "user_id" bigint generated by default as identity primary key,
  "email" varchar(255) not null,
  "user_type" text not null check ("user_type" in ('admin','doctor','patient')),
  "status" text default 'active' check ("status" in ('active','pending','suspended','inactive')),
  "is_active" bigint default 1,
  "created_at" timestamptz not null default now(),
  "last_login" timestamptz default NULL
);

alter table public.users enable row level security;
revoke all on public.users from anon, authenticated;

alter table public.profiles add column legacy_user_id bigint unique references public.users(user_id);

commit;
